// single-item input: one HTTP request in, one profile out.
//
// Accept the domain three ways, because the callers are not all yours. A CRM
// posts JSON, an HTML form posts urlencoded, and a person testing with curl
// puts it on the query string. Supporting one of the three makes an endpoint
// that only works when you already know the trick.
// Read the trigger by name: `Settings` sits between the two and a Set node in
// manual mode replaces the item, so $input here would be the config object and
// every caller would get a 400 for a domain they did in fact send.
const req = $('Someone Asks About A Company').first().json;

const body = req.body || {};
const query = req.query || {};
const raw = body.domain || body.website || body.url ||
            query.domain || query.website || query.url || '';

function host(s) {
  return String(s || '')
    .trim()
    .toLowerCase()
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .replace(/[\/?#].*$/, '')
    .replace(/^.*@/, '');
}

const domain = host(raw);

// `basecamp.com` -> `basecamp`. Two-part TLDs keep their name rather than
// losing it: `example.co.uk` -> `example`, not `co`.
const TWO_PART_TLD = ['co','com','org','net','gov','ac','edu'];
const parts = domain.split('.');
const brand = (parts.length >= 3 && TWO_PART_TLD.indexOf(parts[parts.length - 2]) !== -1
  && parts[parts.length - 1].length === 2)
  ? parts[parts.length - 3]
  : (parts.length >= 2 ? parts[parts.length - 2] : domain);

// A real domain, not a sentence and not an IP. Rejecting this here is what
// keeps a caller's typo from becoming three Bright Data calls and a confident
// profile of nothing.
const valid = /^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$/.test(domain)
  && domain.length <= 253
  && /[a-z]{2,}$/.test(domain.split('.').pop());

return [{ json: {
  domain,
  brand,
  valid,
  given: String(raw).slice(0, 200),
  site_url: valid ? 'https://' + domain : '',
  pricing_url: valid ? 'https://' + domain + '/pricing' : '',
  // Search the brand, not the domain string. Measured live on 2026-08-24:
  // `"basecamp.com" company` returned a data-broker page and an X profile and
  // found no LinkedIn or Crunchbase at all, because almost nobody writes the
  // TLD when they write about a company. The bare brand finds the profiles.
  search_query: valid ? brand + ' company linkedin crunchbase' : '',
}}];

// single-item input: one domain, one home page.
const req = $('Read The Request').first().json;
const raw = $input.first().json;
const md = typeof raw === 'string' ? raw : (raw.data || raw.body || '');

// Measured across templates 24 and 25: a live site returns kilobytes of
// markdown, a domain that does not resolve returns zero bytes. neverError means
// nothing throws, so this is the only place the difference is visible.
const reachable = !!md && md.length > 0;

const text = String(md).replace(/\s+/g, ' ');

// The first heading is what they call themselves. The first paragraph after it
// is usually the positioning line they paid somebody to write.
const h1 = (String(md).match(/^#\s+(.{4,120})$/m) || [])[1] || '';
const title = (text.match(/^\s*#\s*(.{4,120}?)\s/) || [])[1] || h1;

function has(re) { return re.test(text); }

return [{ json: {
  check: 'site',
  domain: req.domain,
  site_reachable: reachable,
  site_bytes: String(md).length,
  headline: String(h1 || title).slice(0, 160),
  positioning: text.slice(0, 700),
  signals: {
    has_pricing_link: has(/\]\([^)]*pricing/i),
    has_docs: has(/\]\([^)]*(docs|developer|api)\b/i),
    has_careers: has(/\]\([^)]*(careers|jobs)\b/i),
    has_login: has(/\]\([^)]*(login|signin|sign-in|app\.)/i),
    has_book_demo: has(/(book a demo|request a demo|talk to sales|get a quote)/i),
    self_serve_signup: has(/(start free|free trial|sign up free|get started free)/i),
  },
}}];

// single-item input: one pricing page.
//
// Worth its own fetch. A home page sells and a pricing page states, and the
// difference between "enterprise" and "$29/seat" decides whether a lead is
// worth a human. When there is no /pricing the Unlocker returns a small body
// rather than an error, so absence is a finding rather than a failure.
const req = $('Read The Request').first().json;
const raw = $input.first().json;
const md = typeof raw === 'string' ? raw : (raw.data || raw.body || '');
const text = String(md).replace(/\s+/g, ' ');

const found = !!md && md.length > 400;

// Prices, in the currencies that actually appear on SaaS pricing pages.
const prices = [];
const RE = /([$\u00a3\u20ac]\s?\d[\d,]*(?:\.\d{2})?)(\s*(?:\/|per\s)\s*(?:mo|month|user|seat|year|yr))?/gi;
let m;
while ((m = RE.exec(text)) !== null && prices.length < 8) {
  const p = (m[1] + (m[2] || '')).replace(/\s+/g, ' ').trim();
  if (prices.indexOf(p) === -1) prices.push(p);
}

// Plan names, from the headings a pricing page almost always uses.
const plans = [];
const PLAN = /^#{2,4}\s+([A-Z][A-Za-z0-9+ ]{2,24})\s*$/gm;
while ((m = PLAN.exec(String(md))) !== null && plans.length < 8) {
  const p = m[1].trim();
  if (p.length > 2 && plans.indexOf(p) === -1) plans.push(p);
}

return [{ json: {
  check: 'pricing',
  domain: req.domain,
  pricing_page_found: found,
  prices,
  plans,
  // "Contact us" with no number on the page is itself the answer: this is a
  // sales-led product, and the lead needs a person.
  enterprise_only: found && prices.length === 0 &&
    /(contact (us|sales)|custom pricing|talk to sales)/i.test(text),
}}];

// single-item input: one company, one search.
const req = $('Read The Request').first().json;
let payload = $input.first().json;

// The SERP zone is called with `format: json`, which returns the whole HTTP
// envelope - { status_code, headers, body } - with the parsed SERP inside
// `body`. Reading `organic` off the top level finds nothing and reports a
// company with no web presence at all.
//
// Read the envelope's own status first. The HTTP node runs with neverError, so
// a bad gateway arrives looking exactly like a successful call with nothing in
// it. Seen live on 2026-08-24: status_code 502, body '', and this node happily
// reported search_ran true with zero results - which is the one thing a fixed
// response shape is supposed to prevent, because the caller then reads "we
// looked and found no coverage" instead of "the lookup broke".
const envelopeStatus = Number((payload && payload.status_code) || 0);
const transportOk = !envelopeStatus || (envelopeStatus >= 200 && envelopeStatus < 300);

if (payload && payload.body != null) payload = payload.body;
if (typeof payload === 'string') {
  try { payload = JSON.parse(payload); } catch (e) { payload = null; }
} else if (payload && typeof payload.data === 'string') {
  try { payload = JSON.parse(payload.data); } catch (e) { payload = null; }
}

const failed = !transportOk || !payload || !!payload.error;
const organic = (!failed && payload && payload.organic) || [];

function host(u) {
  const m = String(u || '').match(/^https?:\/\/([^/?#]+)/);
  return m ? m[1].toLowerCase().replace(/^www\./, '') : '';
}

const mentions = [];
const profiles = {};
for (const o of organic.slice(0, 10)) {
  const h = host(o && o.link);
  const title = String((o && o.title) || '').replace(/\s+/g, ' ').trim();
  if (!title) continue;
  if (/linkedin\.com/.test(h) && !profiles.linkedin) profiles.linkedin = o.link;
  if (/crunchbase\.com/.test(h) && !profiles.crunchbase) profiles.crunchbase = o.link;
  if (/github\.com/.test(h) && !profiles.github) profiles.github = o.link;
  if (h.indexOf(req.domain) !== -1) continue;   // their own pages are not coverage
  mentions.push({ title: title.slice(0, 140), source: h });
}

return [{ json: {
  check: 'search',
  domain: req.domain,
  search_ran: !failed,
  search_status: envelopeStatus || null,
  results_read: organic.length,
  profiles,
  mentions: mentions.slice(0, 5),
}}];

// Assemble one fixed shape, whatever happened above.
//
// The contract matters more than the content. A caller cannot branch on
// "sometimes there is a pricing key" - so every field exists on every response,
// and `checks` says which lookups actually worked. An enrichment API that
// returns a different set of keys per call is one nobody can integrate.
const req = $('Read The Request').first().json;
const site = $('Read The Site').first().json;
const pricing = $('Read The Pricing Page').first().json;
const search = $('Read The Search').first().json;

const model =
  pricing.enterprise_only ? 'sales_led' :
  (pricing.prices.length ? 'self_serve_published' :
   (site.signals.self_serve_signup ? 'self_serve_unpublished' : 'unknown'));

return [{ json: {
  domain: req.domain,
  reachable: site.site_reachable,
  headline: site.headline,
  positioning: site.positioning.slice(0, 400),
  go_to_market: model,
  pricing: {
    page_found: pricing.pricing_page_found,
    plans: pricing.plans,
    prices: pricing.prices,
    enterprise_only: pricing.enterprise_only,
  },
  product_signals: site.signals,
  profiles: search.profiles,
  mentions: search.mentions,
  checks: {
    site: site.site_reachable,
    pricing: pricing.pricing_page_found,
    search: search.search_ran,
  },
}}];

parameters.text:
=Write one paragraph, 40 to 70 words, describing this company for a salesperson who has never heard of them and is about to make contact.

Domain: {{ $json.domain }}
Headline: {{ $json.headline }}
From their site: {{ $json.positioning }}
Go to market: {{ $json.go_to_market }}
Pricing: {{ JSON.stringify($json.pricing) }}
Product signals: {{ JSON.stringify($json.product_signals) }}
What the web says: {{ JSON.stringify($json.mentions) }}

Say what they sell and who to. If pricing figures are present, use them. If the pricing page could not be read, do not guess a price.

Stay inside the findings above - no funding rounds, headcounts, founders or customers that are not there. If the site could not be read at all, say plainly that there was not enough to go on rather than describing a company you cannot see. Plain prose, no markdown, no headings.

