// single-item input: the chain runs executeOnce and answers for the one domain.
//
// A chain node replaces the item with its answer, so the profile assembled
// above would be gone by the time the response is built.
const profile = $('Build The Profile').first().json;
const raw = $input.first().json || {};
const text = String(raw.text || raw.response || raw.output || '').trim();

return [{ json: Object.assign({}, profile, {
  summary: text || 'No summary was generated; use the structured fields.',
  enriched_at: $now.toISO(),
}) }];
